def _markup(self, entry):
        """
        Recursively generates HTML for the current entry.

        Parameters
        ----------
        entry : object
            Object to convert to HTML. Maybe be a single entity or contain multiple and/or nested objects.

        Returns
        -------
        str
            String of HTML formatted json.
        """
        if isinstance(entry, dict):
            return self._markup_dict(entry)
        elif isinstance(entry, list):
            return self._markup_list(entry)
        elif isinstance(entry, str):
            return self._markup_str(entry)
        elif isinstance(entry, int):
            return self._markup_int(entry)
        elif isinstance(entry, float):
            return self._markup_float(entry)
        elif isinstance(entry, bool):
            return self._markup_bool(entry)
        elif entry is None:
            return self._markup_null()
        else:
            raise TypeError('Cannot convert object of type {} to HTML'.format(type(entry)))

